#!/usr/bin/env bash
# Checks the TLS keystore generated by `mvn -Pdocker`: its certificate's subject must match DNAME
# in .env, including non-ASCII characters (#961). Run from the project root after the build.
set -euo pipefail

env_value() {
  sed -n "s/^$1=//p" .env | tail -1
}
keystore="target/docker/tomcat/$(env_value TLS_KEYSTORE_FILE)"
owner=$(keytool -list -v -keystore "$keystore" -storepass "$(env_value TLS_KEYSTORE_PASS)" \
  -alias "$(env_value ALIAS)" | sed -n 's/^Owner: //p')

expected_locality="L=BaileÁthaCliath"
case "$owner" in
  *"$expected_locality"*)
    echo "PASS: TLS certificate owner is $owner"
    ;;
  *)
    echo "FAIL: TLS certificate owner '$owner' does not contain '$expected_locality'"
    exit 1
    ;;
esac
